/// MATRIX backend configuration.
///
/// The production API base defaults to the public MATRIX site; override at
/// build time with:
///   flutter run --dart-define=MATRIX_API_BASE=https://matrix.thamjj13.top
library;

class MatrixConfig {
  static const apiBase = String.fromEnvironment(
    'MATRIX_API_BASE',
    defaultValue: 'https://matrix.thamjj13.top',
  );

  /// Firebase web config for the MATRIX project (public by design — the same
  /// values the web app ships in NEXT_PUBLIC_FIREBASE_*; fill these in
  /// firebase_options.dart generated by `flutterfire configure`).
  static Uri get baseUri => Uri.parse(apiBase);
}
